document.addEventListener('DOMContentLoaded',function(){initMobileMenu();initSmoothScroll();initContactForm();initFAQAccordion();initTestimonialCarousel();});function initMobileMenu(){const menuToggle=document.querySelector('.menu-toggle');const navMenu=document.querySelector('.nav-menu');const navOverlay=document.querySelector('.nav-overlay');const body=document.body;if(!menuToggle||!navMenu)return;let overlay=navOverlay;if(!overlay){overlay=document.createElement('div');overlay.className='nav-overlay';document.body.appendChild(overlay);}
function toggleMenu(){menuToggle.classList.toggle('active');navMenu.classList.toggle('active');overlay.classList.toggle('active');body.style.overflow=navMenu.classList.contains('active')?'hidden':'';}
function closeMenu(){menuToggle.classList.remove('active');navMenu.classList.remove('active');overlay.classList.remove('active');body.style.overflow='';}
menuToggle.addEventListener('click',toggleMenu);overlay.addEventListener('click',closeMenu);navMenu.querySelectorAll('a').forEach(link=>{link.addEventListener('click',closeMenu);});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&navMenu.classList.contains('active')){closeMenu();}});window.addEventListener('resize',function(){if(window.innerWidth>991&&navMenu.classList.contains('active')){closeMenu();}});}
function initSmoothScroll(){document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){const href=this.getAttribute('href');if(href==='#')return;const target=document.querySelector(href);if(target){e.preventDefault();const headerHeight=document.querySelector('.header')?.offsetHeight||0;const targetPosition=target.getBoundingClientRect().top+window.pageYOffset-headerHeight;window.scrollTo({top:targetPosition,behavior:'smooth'});}});});}
function initContactForm(){const whatsappNumber='919830802898';const forms=document.querySelectorAll('#contact-form, #contactForm, #appointmentForm');forms.forEach(form=>{if(!form)return;form.addEventListener('submit',function(e){e.preventDefault();const name=form.querySelector('[name="name"]')?.value||'';const phone=form.querySelector('[name="phone"]')?.value||'';const email=form.querySelector('[name="email"]')?.value||'';const service=form.querySelector('[name="service"]')?.value||'';const petType=form.querySelector('[name="pet-type"]')?.value||'';const petName=form.querySelector('[name="pet-name"]')?.value||'';const date=form.querySelector('[name="date"]')?.value||'';const message=form.querySelector('[name="message"]')?.value||'';if(!name.trim()||!phone.trim()){alert('Please fill in your name and phone number.');return;}
let whatsappMessage=`*New Booking Request from Emily's Pet Heaven Website*\n\n`;
      whatsappMessage += `*Name:* ${name}\n`;
      whatsappMessage += `*Phone:* ${phone}\n`;
      if (email) whatsappMessage += `*Email:* ${email}\n`;
      if (service) whatsappMessage += `*Service:* ${service}\n`;
      if (petType) whatsappMessage += `*Pet Type:* ${petType}\n`;
      if (petName) whatsappMessage += `*Pet Name:* ${petName}\n`;
      if (date) whatsappMessage += `*Preferred Date:* ${date}\n`;
      if (message) whatsappMessage += `*Message:* ${message}\n`;

      // Create WhatsApp URL
      const whatsappURL = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(whatsappMessage)}`;

      // Show confirmation
      const submitBtn = form.querySelector('button[type="submit"]');
      const originalText = submitBtn.innerHTML;
      submitBtn.innerHTML = '<span class="loading"></span>Redirecting to WhatsApp...';
      submitBtn.disabled = true;

      // Redirect to WhatsApp after brief delay
      setTimeout(() => {
        window.open(whatsappURL, '_blank');
        
        // Reset button
        submitBtn.innerHTML = originalText;
        submitBtn.disabled = false;
        
        // Show success alert
        alert('Your booking request has been sent to WhatsApp!We will respond within 24 hours.');
        
        // Reset form
        form.reset();
      }, 500);
    });
  });
}

// ===== FAQ ACCORDION =====
function initFAQAccordion() {
  const faqItems = document.querySelectorAll('.faq-item');

  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    const answer = item.querySelector('.faq-answer');

    if (!question || !answer) return;

    question.addEventListener('click', function() {
      const isActive = item.classList.contains('active');

      // Close all other items (optional - remove for multi-open)
      faqItems.forEach(otherItem => {
        if (otherItem !== item) {
          otherItem.classList.remove('active');
        }
      });

      // Toggle current item
      item.classList.toggle('active');

      // Update ARIA attributes
      question.setAttribute('aria-expanded', !isActive);
    });

    // Keyboard accessibility
    question.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === '') {
        e.preventDefault();
        question.click();
      }
    });
  });
}

// ===== TESTIMONIAL CAROUSEL =====
function initTestimonialCarousel() {
  const carousel = document.querySelector('.testimonial-carousel');
  if (!carousel) return;

  const slidesContainer = carousel.querySelector('.testimonial-slides');
  const slides = carousel.querySelectorAll('.testimonial-slide');
  const prevBtn = carousel.querySelector('.testimonial-prev');
  const nextBtn = carousel.querySelector('.testimonial-next');
  const dotsContainer = carousel.querySelector('.testimonial-dots');

  if (!slidesContainer || slides.length === 0) return;

  let currentIndex = 0;
  let autoplayInterval;
  const autoplayDelay = 5000; // 5 seconds

  // Create dots
  if (dotsContainer) {
    slides.forEach((_, index) => {
      const dot = document.createElement('button');
      dot.className = 'testimonial-dot' + (index === 0 ? 'active' : '');
      dot.setAttribute('aria-label', `Go to testimonial ${index + 1}`);
      dot.addEventListener('click', () => goToSlide(index));
      dotsContainer.appendChild(dot);
    });
  }

  const dots = dotsContainer?.querySelectorAll('.testimonial-dot');

  function updateSlides() {
    // Update slide positions
    slidesContainer.style.transform = `translateX(-${currentIndex * 100}%)`;

    // Update active states
    slides.forEach((slide, index) => {
      slide.classList.toggle('active', index === currentIndex);
    });

    // Update dots
    dots?.forEach((dot, index) => {
      dot.classList.toggle('active', index === currentIndex);
    });
  }

  function goToSlide(index) {
    currentIndex = index;
    if (currentIndex >= slides.length) currentIndex = 0;
    if (currentIndex < 0) currentIndex = slides.length - 1;
    updateSlides();
    resetAutoplay();
  }

  function nextSlide() {
    goToSlide(currentIndex + 1);
  }

  function prevSlide() {
    goToSlide(currentIndex - 1);
  }

  function startAutoplay() {
    autoplayInterval = setInterval(nextSlide, autoplayDelay);
  }

  function stopAutoplay() {
    clearInterval(autoplayInterval);
  }

  function resetAutoplay() {
    stopAutoplay();
    startAutoplay();
  }

  // Event listeners
  if (prevBtn) prevBtn.addEventListener('click', prevSlide);
  if (nextBtn) nextBtn.addEventListener('click', nextSlide);

  // Pause on hover
  carousel.addEventListener('mouseenter', stopAutoplay);
  carousel.addEventListener('mouseleave', startAutoplay);

  // Touch/swipe support
  let touchStartX = 0;
  let touchEndX = 0;

  carousel.addEventListener('touchstart', (e) => {
    touchStartX = e.changedTouches[0].screenX;
  }, { passive: true });

  carousel.addEventListener('touchend', (e) => {
    touchEndX = e.changedTouches[0].screenX;
    handleSwipe();
  }, { passive: true });

  function handleSwipe() {
    const swipeThreshold = 50;
    const diff = touchStartX - touchEndX;

    if (Math.abs(diff) > swipeThreshold) {
      if (diff > 0) {
        nextSlide();
      } else {
        prevSlide();
      }
    }
  }

  // Keyboard navigation
  carousel.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') prevSlide();
    if (e.key === 'ArrowRight') nextSlide();
  });

  // Initialize
  updateSlides();
  startAutoplay();
}

// ===== UTILITY FUNCTIONS =====

// Debounce function
function debounce(func, wait) {
  let timeout;
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout);
      func(...args);
    };
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

// Throttle function
function throttle(func, limit) {
  let inThrottle;
  return function(...args) {
    if (!inThrottle) {
      func.apply(this, args);
      inThrottle = true;
      setTimeout(() => inThrottle = false, limit);
    }
  };
}

// Check if element is in viewport
function isInViewport(element) {
  const rect = element.getBoundingClientRect();
  return (
    rect.top >= 0 &&
    rect.left >= 0 &&
    rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
    rect.right <= (window.innerWidth || document.documentElement.clientWidth)
  );
}

// Format phone number
function formatPhoneNumber(phone) {
  const cleaned = phone.replace(/\D/g, '');
  if (cleaned.length === 10) {
    return cleaned.replace(/(\d{3})(\d{3})(\d{4})/, '$1-$2-$3');
  }
  return phone;
}

// WhatsApp link generator
function generateWhatsAppLink(phone, message = '') {
  const cleanPhone = phone.replace(/\D/g, '');
  const encodedMessage = encodeURIComponent(message);
  return `https://wa.me/${cleanPhone}${message ? '?text=' + encodedMessage : ''}`;
}

// ===== HEADER SCROLL EFFECT =====
(function() {
  const header = document.querySelector('.header');
  if (!header) return;

  let lastScroll = 0;

  window.addEventListener('scroll', throttle(function() {
    const currentScroll = window.pageYOffset;

    if (currentScroll > 100) {
      header.classList.add('scrolled');
    } else {
      header.classList.remove('scrolled');
    }

    lastScroll = currentScroll;
  }, 100));
})();

// ===== ACTIVE NAV LINK =====
(function() {
  const currentPath = window.location.pathname.split('/').pop() || 'index.html';
  const navLinks = document.querySelectorAll('.nav-menu a');

  navLinks.forEach(link => {
    const href = link.getAttribute('href');
    if (href === currentPath || (currentPath === '' && href === 'index.html')) {
      link.classList.add('active');
    }
  });
})();

// ===== EMILY PET'S HEAVEN-ANIMATIONS JAVASCRIPT=====document.addEventListener('DOMContentLoaded',function(){initScrollAnimations();initParallaxEffects();initCounterAnimations();initRevealOnScroll();initTiltEffect('.service-card, .pricing-card, .blog-card-small');});function initRevealOnScroll(){const revealElements=document.querySelectorAll('.reveal-on-scroll');if(revealElements.length===0)return;const viewportHeight=window.innerHeight;revealElements.forEach(function(el){var rect=el.getBoundingClientRect();if(rect.top<viewportHeight+50){el.classList.add('revealed');}});document.documentElement.classList.add('js-reveal-ready');var observerOptions={root:null,rootMargin:'0px 0px -50px 0px',threshold:0.1};var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}});},observerOptions);revealElements.forEach(function(element){if(!element.classList.contains('revealed')){observer.observe(element);}});}
function initScrollAnimations(){const animatedElements=document.querySelectorAll('.scroll-animate');if(animatedElements.length===0)return;if('IntersectionObserver'in window){const observerOptions={root:null,rootMargin:'0px 0px -50px 0px',threshold:0.1};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animated');}});},observerOptions);animatedElements.forEach(element=>{observer.observe(element);});}else{animatedElements.forEach(element=>{element.classList.add('animated');});}}
function initParallaxEffects(){const parallaxElements=document.querySelectorAll('[data-parallax]');if(parallaxElements.length===0)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){return;}
function updateParallax(){const scrollY=window.pageYOffset;parallaxElements.forEach(element=>{const speed=parseFloat(element.dataset.parallax)||0.5;const rect=element.getBoundingClientRect();const elementTop=rect.top+scrollY;const offset=(scrollY-elementTop)*speed;element.style.transform=`translateY(${offset}px)`;});}
let ticking=false;window.addEventListener('scroll',function(){if(!ticking){window.requestAnimationFrame(function(){updateParallax();ticking=false;});ticking=true;}});}
function initCounterAnimations(){const counters=document.querySelectorAll('[data-counter]');if(counters.length===0)return;const observerOptions={root:null,rootMargin:'0px',threshold:0.5};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting&&!entry.target.classList.contains('counted')){animateCounter(entry.target);entry.target.classList.add('counted');}});},observerOptions);counters.forEach(counter=>{observer.observe(counter);});}
function animateCounter(element){const target=parseInt(element.dataset.counter,10);const duration=parseInt(element.dataset.duration,10)||2000;const suffix=element.dataset.suffix||'';const prefix=element.dataset.prefix||'';let startTime=null;const startValue=0;function easeOutQuart(t){return 1-Math.pow(1-t,4);}
function updateCounter(currentTime){if(!startTime)startTime=currentTime;const elapsed=currentTime-startTime;const progress=Math.min(elapsed/duration,1);const easedProgress=easeOutQuart(progress);const currentValue=Math.floor(startValue+(target-startValue)*easedProgress);element.textContent=prefix+currentValue.toLocaleString()+suffix;if(progress<1){requestAnimationFrame(updateCounter);}}
requestAnimationFrame(updateCounter);}
function initTypingAnimation(){const typingElements=document.querySelectorAll('[data-typing]');typingElements.forEach(element=>{const text=element.dataset.typing;const speed=parseInt(element.dataset.speed,10)||100;let index=0;element.textContent='';element.style.borderRight='2px solid var(--color-primary)';function type(){if(index<text.length){element.textContent+=text.charAt(index);index++;setTimeout(type,speed);}else{setTimeout(()=>{element.style.borderRight='none';},1000);}}
const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){type();observer.unobserve(entry.target);}});},{threshold:0.5});observer.observe(element);});}
function animateStaggered(elements,animationClass,delay=100){elements.forEach((element,index)=>{setTimeout(()=>{element.classList.add(animationClass);},index*delay);});}
function revealOnScroll(selector,options={}){const elements=document.querySelectorAll(selector);const defaultOptions={threshold:0.1,rootMargin:'0px 0px -50px 0px',animationClass:'revealed',stagger:false,staggerDelay:100};const config={...defaultOptions,...options};const observer=new IntersectionObserver((entries)=>{entries.forEach((entry,index)=>{if(entry.isIntersecting){if(config.stagger){setTimeout(()=>{entry.target.classList.add(config.animationClass);},index*config.staggerDelay);}else{entry.target.classList.add(config.animationClass);}
observer.unobserve(entry.target);}});},{threshold:config.threshold,rootMargin:config.rootMargin});elements.forEach(element=>{observer.observe(element);});}
function animateSVGPath(svgElement){const paths=svgElement.querySelectorAll('path');paths.forEach(path=>{const length=path.getTotalLength();path.style.strokeDasharray=length;path.style.strokeDashoffset=length;path.style.transition='stroke-dashoffset 2s ease-in-out';path.style.strokeDashoffset='0';});}
function initMouseFollow(selector){const element=document.querySelector(selector);if(!element)return;document.addEventListener('mousemove',(e)=>{const x=(e.clientX/window.innerWidth-0.5)*20;const y=(e.clientY/window.innerHeight-0.5)*20;element.style.transform=`translate(${x}px,${y}px)`;});}
function initTiltEffect(selector){const cards=document.querySelectorAll(selector);if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){return;}
cards.forEach(card=>{card.addEventListener('mousemove',(e)=>{const rect=card.getBoundingClientRect();const x=e.clientX-rect.left;const y=e.clientY-rect.top;const centerX=rect.width/2;const centerY=rect.height/2;const rotateX=(y-centerY)/10;const rotateY=(centerX-x)/10;card.style.transform=`perspective(1000px)rotateX(${rotateX}deg)rotateY(${rotateY}deg)scale3d(1.02,1.02,1.02)`;});card.addEventListener('mouseleave',()=>{card.style.transform='perspective(1000px) rotateX(0) rotateY(0) scale3d(1, 1, 1)';});});}
function initMagneticButtons(selector){const buttons=document.querySelectorAll(selector);if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){return;}
buttons.forEach(button=>{button.addEventListener('mousemove',(e)=>{const rect=button.getBoundingClientRect();const x=e.clientX-rect.left-rect.width/2;const y=e.clientY-rect.top-rect.height/2;button.style.transform=`translate(${x*0.3}px,${y*0.3}px)`;});button.addEventListener('mouseleave',()=>{button.style.transform='translate(0, 0)';});});}
function initScrollProgress(){const progressBar=document.querySelector('.scroll-progress');if(!progressBar)return;window.addEventListener('scroll',()=>{const scrollTop=window.pageYOffset;const docHeight=document.documentElement.scrollHeight-window.innerHeight;const progress=(scrollTop/docHeight)*100;progressBar.style.width=`${progress}%`;});}
function initLazyLoad(){const lazyImages=document.querySelectorAll('img[data-src]');if('IntersectionObserver'in window){const imageObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;img.src=img.dataset.src;img.removeAttribute('data-src');img.classList.add('loaded');imageObserver.unobserve(img);}});},{rootMargin:'50px 0px'});lazyImages.forEach(img=>{imageObserver.observe(img);});}else{lazyImages.forEach(img=>{img.src=img.dataset.src;img.removeAttribute('data-src');});}}
window.AnimationUtils={animateStaggered,revealOnScroll,animateSVGPath,initMouseFollow,initTiltEffect,initMagneticButtons,initScrollProgress,initLazyLoad,animateCounter};